// Edit these values for each manual run.
const config = {
  source_url: 'https://www.youtube.com/watch?v=Sn3H5UzsDoY',
  pilot: true,
  force_reprocess: false,
  // Pilot only: if no clip reaches SCORING_V1, continue with the best non-HIGH clip as REVIEW.
  allow_below_threshold: true,
  max_candidates: 10,
  // Long-form: 'best_of' (highlights in chronological order) | 'continuous' (one long stretch).
  mode: 'best_of',
  target_minutes: 5,
  upload: true, // false = stop after render + metadata (testing)
  // Channel and the person this run is about (override per run via webhook body).
  channel_name: 'Radar Patriota',
  template: 'longform',
  subject_name: 'Lucas Pavanato',
  subject_notes: 'Grafia correta: Pavanato (um T). Deputado federal eleito por São Paulo (PL), ex-vereador.',
  subject_misspellings: ['Pavanatto'],
};

// Webhook runs (scripts/run-pilot.sh) override the defaults above.
let body = {};
try { body = $('Webhook').first().json.body || {}; } catch { /* manual run */ }
if (body.source_url) config.source_url = String(body.source_url);
if (body.force_reprocess !== undefined) config.force_reprocess = body.force_reprocess === true || body.force_reprocess === 'true';
for (const k of ['subject_name', 'subject_notes', 'channel_name', 'template']) if (body[k]) config[k] = String(body[k]);
if (Array.isArray(body.subject_misspellings)) config.subject_misspellings = body.subject_misspellings.map(String);
if (['best_of', 'continuous'].includes(body.mode)) config.mode = body.mode;
if (Number(body.target_minutes) > 0) config.target_minutes = Math.min(25, Number(body.target_minutes));
if (body.upload !== undefined) config.upload = body.upload === true || body.upload === 'true';
if (body.allow_below_threshold !== undefined) config.allow_below_threshold = body.allow_below_threshold === true || body.allow_below_threshold === 'true';

const m = config.source_url.match(/(?:v=|youtu\.be\/|shorts\/|live\/)([A-Za-z0-9_-]{11})/);
if (!m) throw new Error('CONFIG_INVALID: could not extract YouTube video id from source_url');

return [{ json: { ...config, source_video_id: m[1], started_at: new Date().toISOString() } }];

// Idempotency (docs/plan.md §31): skip videos already in flight or published, unless forced.
const config = $('CONFIG').first().json;
const row = $input.all().map((i) => i.json).find((r) => r.youtube_id === `${config.source_video_id}:long`);
const STALE_MS = 2 * 60 * 60 * 1000; // a PROCESSING row older than this is a crashed run
const now = new Date();
// Test runs (upload=false) never touch the real row and skip the duplicate check.
const key = `${config.source_video_id}:long` + (config.upload ? '' : ':dryrun');
if (config.upload && row && !config.force_reprocess) {
  const active = ['PROCESSING', 'CLIPPED', 'SELECTED'].includes(row.status);
  const stale = active && now - new Date(row.updated_at) > STALE_MS;
  if (row.status === 'UPLOADED' || (active && !stale)) {
    console.log(`SKIPPED_DUPLICATE: ${config.source_video_id} is ${row.status} (youtube_output_id=${row.youtube_output_id || '-'})`);
    return [];
  }
}
return [{ json: {
  youtube_id: key,
  source_url: config.source_url,
  execution_id: String($execution.id),
  status: 'PROCESSING',
  error_reason: '',
  discovered_at: row?.discovered_at ?? now.toISOString(),
  created_at: row?.created_at ?? now.toISOString(),
  updated_at: now.toISOString(),
} }];

const res = $input.first().json;
if (!res?.job_id) throw new Error(`CLIPPER_SUBMIT_FAILED: ${JSON.stringify(res).slice(0, 300)}`);
return [{ json: { ...$('CONFIG').first().json, job_id: res.job_id } }];

// Polls a clipper job; loops back to WAIT PREPARE while queued/running.
const MAX_POLLS = 120;
const res = $input.first().json;
const ctx = $('WAIT PREPARE').first().json;
const poll = $runIndex + 1;

if (res?.status === 'queued' || res?.status === 'running') {
  if (poll >= MAX_POLLS) throw new Error(`CLIPPER_TIMEOUT: job ${ctx.job_id} still ${res.status} after ${poll} polls`);
  return [{ json: { ...ctx, job_status: res.status, polls: poll } }];
}
if (res?.status === 'done' && res.result) {
  return [{ json: { ...ctx, job_status: 'done', polls: poll, result: res.result } }];
}
throw new Error(`${res?.error_code ?? 'CLIPPER_FAILED'}: ${res?.error_message ?? JSON.stringify(res).slice(0, 300)}`);

const S = $('CONFIG').first().json; // channel_name, subject_name, subject_notes
// Proofreads the captions of the selected clip: only evident ASR errors, never style or meaning.
const clip = $input.first().json;
const prep = $('BUILD PLAN REQUEST').first().json.result;
const ids = new Set();
for (const p of clip.parts) for (let i = p.start_id; i <= p.end_id; i++) ids.add(i);
const sentences = prep.sentences.filter((s) => ids.has(s.id));
const around = prep.sentences.filter((s) => s.id >= Math.min(...ids) - 4 && s.id < Math.min(...ids));

const SYSTEM = `Você revisa legendas geradas por transcrição automática (Whisper) de um vídeo em português.
Pessoa principal do vídeo: ${S.subject_name} (${S.subject_notes}).

Corrija SOMENTE erros evidentes de transcrição: nomes próprios, números, datas, siglas,
instituições, e palavras trocadas por outras de som parecido que o CONTEXTO deixa claro
(ex.: "presos do Rio de Janeiro" quando o assunto são os presos do 8 de janeiro).

NÃO reescreva o estilo, NÃO corrija a gramática da fala, NÃO remova hesitações ou repetições,
NÃO resuma, NÃO mude o sentido. Na dúvida, não corrija.

Retorne apenas as frases que precisam de correção, com o texto COMPLETO corrigido da frase,
e em "changes" descreva cada troca no formato "antes → depois".`;

const schema = {
  type: 'object', additionalProperties: false, required: ['fixes'],
  properties: { fixes: { type: 'array', items: {
    type: 'object', additionalProperties: false, required: ['id', 'text', 'changes'],
    properties: { id: { type: 'integer' }, text: { type: 'string' }, changes: { type: 'array', items: { type: 'string' } } },
  } } },
};

return [{ json: { ...clip, request: { provider: 'auto', system: SYSTEM, schema, prompt:
`VÍDEO: "${prep.title}" — ${prep.channel}

CONTEXTO (frases ao redor, não corrigir):
${around.map((s) => `[${s.id}] ${s.text}`).join('\n')}

FRASES A REVISAR:
${sentences.map((s) => `[${s.id}] ${s.text}`).join('\n')}` } } }];

// Applies proofreading fixes (only to sentences of this clip). Failures are logged, not fatal.
const res = $input.first().json;
const { request, ...clip } = $('BUILD PROOFREAD REQUEST').first().json;
const ids = new Set();
for (const p of clip.parts) for (let i = p.start_id; i <= p.end_id; i++) ids.add(i);
const fixes = {};
const changes = [];
if (res?.ok && Array.isArray(res.json?.fixes)) {
  for (const f of res.json.fixes) {
    if (!ids.has(f.id) || !f.text?.trim()) continue;
    fixes[String(f.id)] = f.text.trim();
    changes.push(...(f.changes || []).map((c) => `[${f.id}] ${c}`));
  }
} else {
  console.log(`PROOFREAD_SKIPPED: ${res?.error_code ?? 'no response'} ${res?.error_message ?? ''}`);
}
console.log(JSON.stringify({ proofread_changes: changes }));
return [{ json: { ...clip, sentence_fixes: fixes, proofread_changes: changes } }];

const S = $('CONFIG').first().json; // channel_name, subject_name, subject_notes
// Title + description (docs/plan.md §24-25) in a single call.
const clip = $input.first().json;
const SYSTEM = `Você é editor de vídeos longos (16:9) do canal independente e não oficial "${S.channel_name}",
que publica trechos de declarações públicas. Este vídeo é de ${S.subject_name} (${S.subject_notes}).

TÍTULO
- Alta retenção, despertando curiosidade SEM inventar fatos e sem alterar o significado da fala.
- Prefira: curiosidade, contraste, resposta, surpresa, conflito real, assunto atual, afirmação
  forte realmente existente no vídeo.
- Evite: clickbait falso, caixa alta excessiva, afirmações não presentes, insultos, inferências
  sobre intenção, propaganda política personalizada.
- Máximo 80 caracteres. Sem hashtags no título. Crie 5 opções e escolha a melhor.

DESCRIÇÃO
- Máximo 600 caracteres, 2 parágrafos curtos: o que acontece no vídeo e por que assistir. NÃO inclua URL, linha de fonte, aviso de canal nem hashtags:
  isso é adicionado automaticamente depois.
- Explique brevemente o contexto, deixe claro que é um trecho, identifique a fonte original,
  não atribua nada que não tenha sido dito, tom editorial.

MANCHETE (cartão de título no início do vídeo e thumbnail):
- headline_kicker: UMA expressão de impacto, escolha a que combina com a fala:
  "EITA!", "OLHA ISSO!", "ATENÇÃO!", "CONCORDA?", "POLÊMICA!", "SINCERÃO!", "RESPONDEU!",
  "URGENTE!" (só se o tema for notícia do dia), "BOMBA!" (só se a fala revela algo novo e grave).
  Nunca use "EXCLUSIVO!".
- headline_text: até 32 caracteres, caixa alta, sujeito + verbo forte, ATRIBUÍVEL à fala
  (ex.: "PAVANATO DETONA O PT", "PAVANATO RESPONDE JORNALISTA"). Pode ser enfático, mas não pode
  afirmar fato que não está na fala nem acusar alguém de crime.

TAGS: 5 a 8 tags curtas em português (sem #).
HASHTAGS: 3 a 5, sem espaços, começando com #; não inclua #${S.subject_name.replace(/\s+/g, '')} (já entra).`;

const schema = {
  type: 'object', additionalProperties: false,
  required: ['title', 'alternatives', 'hook', 'description', 'tags', 'hashtags', 'headline_kicker', 'headline_text'],
  properties: {
    title: { type: 'string' }, alternatives: { type: 'array', items: { type: 'string' } },
    hook: { type: 'string' }, description: { type: 'string' },
    tags: { type: 'array', items: { type: 'string' } }, hashtags: { type: 'array', items: { type: 'string' } },
    headline_kicker: { type: 'string' }, headline_text: { type: 'string' },
  },
};
return [{ json: { ...clip, request: { provider: 'auto', system: SYSTEM, schema, prompt:
`FONTE: ${clip.source_channel} — "${clip.source_title}"
URL: ${clip.source_url}

CONTEXTO: ${clip.context_text || '-'}
PERGUNTA INCLUÍDA: ${clip.question || '-'}
ASSUNTO: ${clip.main_topic}

RESUMO: ${clip.summary}
CAPÍTULOS: ${clip.parts.filter((p) => p.role === 'segment').map((p) => p.chapter).join(' | ')}

TRANSCRIÇÃO DOS TRECHOS:
${clip.transcript}` } } }];

const S = $('CONFIG').first().json; // channel_name, subject_name, subject_notes
// Validates metadata and appends the mandatory source/notice lines (never left to the LLM).
const res = $input.first().json;
const { request, ...clip } = $('BUILD METADATA REQUEST').first().json;
if (!res?.ok || !res.json?.title) throw new Error(`${res?.error_code ?? 'LLM_INVALID_JSON'}: metadata ${res?.error_message ?? 'missing title'}`);
const m = res.json;

const clean = (s) => String(s || '').replace(/[<>]/g, '').replace(/\s+/g, ' ').trim();
let title = clean(m.title).replace(/#\S+/g, '').trim();
if (!title) throw new Error('LLM_INVALID_JSON: empty title');
if (title.length > 100) title = title.slice(0, 97).replace(/\s+\S*$/, '') + '...';
const bad = (S.subject_misspellings || []).find((x) => new RegExp(`\\b${x}\\b`, 'i').test(title + ' ' + m.description));
if (bad) throw new Error(`METADATA_INVALID: misspelled name (${bad})`);

const tag = (h) => '#' + String(h).replace(/^#/, '').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9_]/g, '');
const subjectTag = tag(S.subject_name);
const extra = [...new Set((m.hashtags || []).map(tag))].filter((h) => h.length > 2 && h !== subjectTag && h.toLowerCase() !== '#shorts');
const hashtags = [subjectTag, ...extra.slice(0, 4)];
// The source line is added below; drop any "Fonte..." sentence the model wrote anyway.
let body = clean(m.description).replace(/(^|\s)Fonte( original)?\s*:.*?(\.(?=\s|$)|$)/gi, ' ').replace(/\s+/g, ' ').trim();
if (body.length > 900) body = body.slice(0, 897).replace(/\s+\S*$/, '') + '...';
const descriptionParts = { body, source: `Fonte: ${clip.source_channel} — ${clip.source_url}`, note: `Trecho editado. ${S.channel_name} é um canal independente, sem vínculo com as pessoas exibidas.`, hashtags: hashtags.join(' ') };
const description = [
  body,
  '',
  `Fonte: ${clip.source_channel} — ${clip.source_url}`,
  `Trecho editado. ${S.channel_name} é um canal independente, sem vínculo com as pessoas exibidas.`,
  '',
  hashtags.join(' '),
].join('\n');
const tags = [...new Set([S.subject_name, S.subject_name.split(' ').slice(-1)[0], S.channel_name, ...(m.tags || []).map(clean)])].filter(Boolean).slice(0, 12);

// On-video headline: controlled kicker list, short attributable line, theme by urgency.
const KICKERS = ['EITA!', 'OLHA ISSO!', 'ATENÇÃO!', 'CONCORDA?', 'POLÊMICA!', 'SINCERÃO!', 'RESPONDEU!', 'URGENTE!', 'BOMBA!'];
let kicker = clean(m.headline_kicker).toUpperCase();
if (!KICKERS.includes(kicker)) kicker = 'EITA!';
let headline = clean(m.headline_text).toUpperCase().replace(/#\S+/g, '').trim();
if (!headline) headline = title.toUpperCase();
if (headline.length > 34) headline = headline.slice(0, 34).replace(/\s+\S*$/, '');
const theme = ['URGENTE!', 'BOMBA!'].includes(kicker) ? 'alerta' : 'brasil';

return [{ json: { ...clip, descriptionParts, headline_kicker: kicker, headline_text: headline, theme, title, title_alternatives: m.alternatives, hook: m.hook, description, tags } }];

const res = $input.first().json;
if (!res?.job_id) throw new Error(`RENDER_SUBMIT_FAILED: ${JSON.stringify(res).slice(0, 300)}`);
return [{ json: { ...$('VALIDATE METADATA').first().json, job_id: res.job_id } }];

// Polls a clipper job; loops back to WAIT RENDER while queued/running.
const MAX_POLLS = 120;
const res = $input.first().json;
const ctx = $('WAIT RENDER').first().json;
const poll = $runIndex + 1;

if (res?.status === 'queued' || res?.status === 'running') {
  if (poll >= MAX_POLLS) throw new Error(`RENDER_TIMEOUT: job ${ctx.job_id} still ${res.status} after ${poll} polls`);
  return [{ json: { ...ctx, job_status: res.status, polls: poll } }];
}
if (res?.status === 'done' && res.result) {
  return [{ json: { ...ctx, job_status: 'done', polls: poll, result: res.result } }];
}
throw new Error(`${res?.error_code ?? 'RENDER_FAILED'}: ${res?.error_message ?? JSON.stringify(res).slice(0, 300)}`);

// Final description with YouTube chapters (first at 00:00, >= 3 entries, >= 10s each).
const ctx = $input.first().json;
const { result, job_id, job_status, polls, ...clip } = ctx;
if (result.width !== 1920 || result.height !== 1080) throw new Error(`RENDER_FAILED: unexpected size ${result.width}x${result.height}`);
const ts = (s) => { s = Math.floor(s); const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), x = s % 60;
  return (h ? `${h}:${String(m).padStart(2, '0')}` : `${String(m).padStart(2, '0')}`) + `:${String(x).padStart(2, '0')}`; };
let chapters = result.chapters.map((c) => ({ title: c.title, start: c.start }));
if (!chapters.length || chapters[0].start > 0) chapters = [{ title: 'Abertura', start: 0 }, ...chapters];
chapters = chapters.filter((c, i, a) => i === 0 || c.start - a[i - 1].start >= 10);
const d = clip.descriptionParts;
const description = [d.body, '', ...(chapters.length >= 3 ? ['Capítulos:', ...chapters.map((c) => `${ts(c.start)} ${c.title}`), ''] : []),
  d.source, d.note, '', d.hashtags].join('\n').slice(0, 4900);
return [{ json: { ...clip, description, chapters, video_file: result.container_path, video_file_name: result.file_name,
  thumbnail_file: result.thumbnail_container_path,
  render: { width: result.width, height: result.height, duration: result.duration } } }];

const c = $input.first().json;
return [{ json: {
  youtube_id: `${c.source_video_id}:long` + ($('CONFIG').first().json.upload ? '' : ':dryrun'), source_channel: c.source_channel, source_title: c.source_title,
  best_clip_id: c.clip_id, editorial_score: c.score, editorial_risk: c.risk, below_threshold: !!c.below_threshold,
  title: c.title, video_file: c.video_file, status: $('CONFIG').first().json.upload ? 'SELECTED' : 'DRY_RUN', updated_at: new Date().toISOString(),
} }];

const res = $input.first().json;
const meta = $('VALIDATE METADATA').first().json;
const id = res?.id ?? res?.uploadId;
if (!id) throw new Error(`YOUTUBE_UPLOAD_FAILED: ${JSON.stringify(res).slice(0, 300)}`);
console.log(`UPLOADED https://youtu.be/${id}`);
return [{ json: {
  youtube_id: `${meta.source_video_id}:long`, youtube_output_id: id, status: 'UPLOADED', error_reason: '',
  updated_at: new Date().toISOString(),
} }];

const meta = $('VALIDATE METADATA').first().json;
const up = $('CHECK UPLOAD').first().json;
const thumbErr = $('THUMB ROW').first().json.error_reason;
return [{ json: {
  status: 'UPLOADED', thumbnail: thumbErr || 'ok', chapters: $('DONE').first().json.chapters, youtube_url: `https://youtu.be/${up.youtube_output_id}`, studio_url: `https://studio.youtube.com/video/${up.youtube_output_id}/edit`,
  title: meta.title, description: $('DONE').first().json.description, tags: meta.tags, title_alternatives: meta.title_alternatives,
  clip_id: meta.clip_id, score: meta.score, risk: meta.risk, below_threshold: !!meta.below_threshold,
  video_file: $('DONE').first().json.video_file, headline: `${meta.headline_kicker} ${meta.headline_text}`, source_url: meta.source_url,
} }];

// Long-form plan: cold-open hook + chaptered segments, chosen from the full transcript.
const S = $('CONFIG').first().json;
const ctx = $input.first().json;
const prep = ctx.result;
if (!prep.sentences?.length) throw new Error('TRANSCRIPT_EMPTY: no sentences');
const mmss = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;
const lines = prep.sentences.map((s) => `[${s.id}] (${mmss(s.start)} · ${(s.end - s.start).toFixed(1)}s) ${s.text}`).join('\n');
const target = S.target_minutes * 60;

const MODE = S.mode === 'continuous'
  ? `MODO: CORTE CONTÍNUO. Escolha UM trecho contínuo (o melhor) com cerca de ${S.target_minutes} minutos
(entre ${Math.round(target * 0.6)}s e ${Math.round(target * 1.4)}s) e divida-o em 3 a 6 CAPÍTULOS nas mudanças de
assunto: os segmentos devem ser CONTÍGUOS (o start_id de cada um = end_id do anterior + 1).`
  : `MODO: MELHORES MOMENTOS. Escolha de 4 a 8 segmentos em ORDEM CRONOLÓGICA, cada um com 20 a 120
segundos, somando cerca de ${S.target_minutes} minutos (entre ${Math.round(target * 0.6)}s e ${Math.round(target * 1.4)}s).`;

const SYSTEM = `Você edita vídeos longos (16:9) do canal independente "${S.channel_name}" a partir de um vídeo-fonte.
Pessoa principal: ${S.subject_name} (${S.subject_notes}).

${MODE}

REGRAS
- Some as durações das frases ("4.2s") para respeitar os tempos.
- Segmentos em que ${S.subject_name} é protagonista (fala ou interage); diálogos e discussões valem.
- Cada segmento começa no início de uma ideia e termina com a ideia CONCLUÍDA. Não corte no meio.
- Não altere o sentido do que foi dito; não monte sequências que sugiram algo que não aconteceu.
- chapter: título do capítulo, até 40 caracteres, factual e chamativo, sem afirmar o que não foi dito.
- start_trim_text / end_trim_text: palavras de OUTRA pessoa coladas no início/fim da frase, para cortar
  (copie exatamente); use "" quando não houver.
- HOOK (abertura): um momento de 6 a 20 segundos, o mais forte do vídeo, que funcione sozinho como
  chamada. Pode ser de dentro de um dos segmentos (vai se repetir depois, é normal).
- thumbnail_sentence_id: número de UMA frase dita por ${S.subject_name} (não por outra pessoa), no
  momento mais expressivo, para a thumbnail.
- Não avalie se concorda politicamente.`;

const seg = { type: 'object', additionalProperties: false,
  required: ['start_id', 'end_id', 'start_trim_text', 'end_trim_text', 'chapter', 'why'],
  properties: { start_id: { type: 'integer' }, end_id: { type: 'integer' }, start_trim_text: { type: 'string' },
    end_trim_text: { type: 'string' }, chapter: { type: 'string' }, why: { type: 'string' } } };
const schema = { type: 'object', additionalProperties: false, required: ['hook', 'segments', 'title_hint', 'summary', 'thumbnail_sentence_id'],
  properties: { hook: seg, thumbnail_sentence_id: { type: 'integer' }, segments: { type: 'array', items: seg }, title_hint: { type: 'string' }, summary: { type: 'string' } } };

return [{ json: { ...ctx, request: { provider: 'auto', system: SYSTEM, schema,
  prompt: `VÍDEO: "${prep.title}" — canal ${prep.channel} (publicado ${prep.upload_date})\n\nTRANSCRIÇÃO (frases):\n${lines}` } } }];

// Validates the plan and turns it into render parts (hook + segments).
const S = $('CONFIG').first().json;
const res = $input.first().json;
const prep = $('BUILD PLAN REQUEST').first().json.result;
if (!res?.ok || !Array.isArray(res.json?.segments)) throw new Error(`${res?.error_code ?? 'LLM_INVALID_JSON'}: planner ${res?.error_message ?? 'no segments'}`);
const byId = new Map(prep.sentences.map((s) => [s.id, s]));
const norm = (t) => t.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9 ]/g, '').split(/\s+/).filter(Boolean);
const skip = (s, trim, atEnd) => {
  const t = norm(trim || ''); if (!t.length) return 0;
  const ws = norm(s.text); const sl = atEnd ? ws.slice(ws.length - t.length) : ws.slice(0, t.length);
  return t.length < ws.length && sl.join(' ') === t.join(' ') ? t.length : 0;
};
const toPart = (x, role) => {
  const a = byId.get(x.start_id), b = byId.get(x.end_id);
  if (!a || !b || x.end_id < x.start_id) return null;
  const ss = skip(a, x.start_trim_text, false), se = x.end_id === x.start_id && ss ? 0 : skip(b, x.end_trim_text, true);
  const text = prep.sentences.filter((s) => s.id >= x.start_id && s.id <= x.end_id).map((s) => s.text).join(' ').split(/\s+/);
  return { start_id: x.start_id, end_id: x.end_id, role, skip_words_start: ss, skip_words_end: se,
    chapter: (x.chapter || '').slice(0, 48), why: x.why, duration: b.end - a.start,
    text: text.slice(ss, text.length - se).join(' ') };
};
const rejected = [];
let segments = res.json.segments.map((x) => toPart(x, 'segment')).filter((p, i) => p || !rejected.push({ i, reason: 'invalid ids' }));
segments.sort((p, q) => p.start_id - q.start_id);
segments = segments.filter((p, i) => {
  if (p.duration < 12 || p.duration > 420) { rejected.push({ chapter: p.chapter, reason: `duration ${p.duration.toFixed(0)}s` }); return false; }
  if (i > 0 && p.start_id <= segments[i - 1].end_id) { rejected.push({ chapter: p.chapter, reason: 'overlap' }); return false; }
  return true;
});
const hook = toPart(res.json.hook, 'hook');
const total = segments.reduce((t, p) => t + p.duration, 0) + (hook?.duration || 0);
console.log(JSON.stringify({ segments: segments.length, total_seconds: Math.round(total), rejected }));
if (segments.length < 2) throw new Error(`NO_CLIPS_RETURNED: planner gave ${segments.length} valid segments`);
const parts = [...(hook && hook.duration >= 4 && hook.duration <= 30 ? [hook] : []), ...segments];
return [{ json: {
  clip_id: `${prep.video_id}_long_${S.mode}`, parts, mode: S.mode, title: res.json.title_hint, summary: res.json.summary,
  transcript: segments.map((p) => p.text).join('\n'), context_text: '', question: null,
  source_url: prep.source_url, source_video_id: prep.video_id, source_title: prep.title, source_channel: prep.channel,
  duration: Math.round(total),
  thumbnail_sentence_id: byId.has(res.json.thumbnail_sentence_id) ? res.json.thumbnail_sentence_id : null,
} }];

// Fidelity review of the whole edit (one call). Only meaning-changing problems block a segment.
const S = $('CONFIG').first().json;
const plan = $input.first().json;
const SYSTEM = `Você revisa a montagem de um vídeo longo (${plan.mode === 'continuous' ? 'corte contínuo' : 'melhores momentos'})
do canal independente "${S.channel_name}" com trechos de ${S.subject_name}.

Para cada segmento decida:
- block = true SOMENTE se: a montagem muda o sentido do que foi dito; a ordem/abertura leva o espectador a
  concluir algo que não aconteceu; uma fala fica atribuída à pessoa errada de forma que muda o sentido;
  ou o trecho é ininteligível.
- block = false para problemas menores (começa no meio de uma conversa mas dá para entender, palavras
  truncadas — são erros de transcrição corrigidos à parte —, fala autodeclarada não verificada, tom
  hostil da própria situação). Registre-os em reason.
- chapter: reescreva o título do capítulo para ser fiel e atribuído (ex.: "Pavanato diz que..."),
  chamativo, até 40 caracteres. Pode manter o original se estiver bom.
risk do conjunto: LOW, MEDIUM ou HIGH. Não avalie se concorda politicamente.`;
const schema = { type: 'object', additionalProperties: false, required: ['risk', 'issues', 'segments'],
  properties: { risk: { type: 'string', enum: ['LOW', 'MEDIUM', 'HIGH'] }, issues: { type: 'array', items: { type: 'string' } },
    segments: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['index', 'block', 'reason', 'chapter'],
      properties: { index: { type: 'integer' }, block: { type: 'boolean' }, reason: { type: 'string' }, chapter: { type: 'string' } } } } } };
const body = plan.parts.map((p, i) => `#${i} [${p.role === 'hook' ? 'ABERTURA' : 'SEGMENTO'}] ${p.chapter && p.role !== 'hook' ? `CAPÍTULO: ${p.chapter}\n` : ''}${p.text}`).join('\n\n');
return [{ json: { ...plan, request: { provider: 'auto', system: SYSTEM, schema,
  prompt: `Segmentos na ordem em que aparecerão no vídeo:\n\n${body}` } } }];

// Drops segments the review flagged; a HIGH-risk edit stops the run (unless pilot fallback).
const res = $input.first().json;
const { request, ...plan } = $('BUILD REVIEW REQUEST').first().json;
const S = $('CONFIG').first().json;
if (!res?.ok || !res.json) throw new Error(`${res?.error_code ?? 'LLM_INVALID_JSON'}: review ${res?.error_message ?? ''}`);
const verdict = new Map((res.json.segments || []).map((s) => [s.index, s]));
const dropped = [];
const parts = plan.parts.filter((p, i) => {
  const v = verdict.get(i);
  if (v && v.block) { dropped.push({ i, chapter: p.chapter, reason: v.reason }); return false; }
  if (v && v.chapter && p.role === 'segment') p.chapter = v.chapter.slice(0, 48);
  return true;
});
console.log(JSON.stringify({ review_risk: res.json.risk, issues: res.json.issues, dropped }));
if (parts.filter((p) => p.role === 'segment').length < 2) throw new Error('ALL_CLIPS_REJECTED: review left fewer than 2 segments');
if (res.json.risk === 'HIGH' && !(S.pilot && S.allow_below_threshold)) throw new Error(`ALL_CLIPS_REJECTED: review risk HIGH (${res.json.issues.join('; ')})`);
return [{ json: { ...plan, parts, risk: res.json.risk, review_issues: res.json.issues, dropped,
  score: null, status: res.json.risk === 'HIGH' ? 'REVIEW' : 'SELECTED', below_threshold: res.json.risk === 'HIGH',
  main_topic: plan.summary } }];

const res = $input.first().json;
const up = $('CHECK UPLOAD').first().json;
const ok = !!res?.items?.length || !!res?.kind;
if (!ok) console.log(`THUMBNAIL_FAILED: ${JSON.stringify(res).slice(0, 300)}`);
return [{ json: { ...up, error_reason: ok ? '' : `THUMBNAIL_FAILED: ${(res?.error?.message || JSON.stringify(res)).slice(0, 200)}` } }];
